// CRE-536: a second Supabase Auth session, scoped to the client portal.
//
// `./client.ts` is the admin app's one shared session, regenerated by
// Lovable and not to be edited directly. The portal needs its OWN session
// — a client signed in to their portal must never share storage with (or
// be confused for) an admin signed in to /admin in the same browser, and
// an admin previewing a client's portal (`?as=admin`) keeps using their
// own admin session rather than this one. A distinct `storageKey` is what
// keeps the two apart in the same browser's localStorage.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { brokeredPreviewStorage } from './previewAuthStorage';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

export const supabasePortal = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: brokeredPreviewStorage(),
    storageKey: 'sb-portal-auth-token',
    persistSession: true,
    autoRefreshToken: true,
  },
});
